<?php use App\Core\Csrf; use App\Helpers\ViewHelper;
$paymentMethods = ['cod'=>'COD','bank_transfer'=>'Chuyển khoản','momo'=>'MoMo','vnpay'=>'VNPay','zalopay'=>'ZaloPay'];
$paymentStatuses = ['pending'=>'Chờ thanh toán','processing'=>'Đang xử lý','paid'=>'Đã thanh toán','failed'=>'Thất bại','cancelled'=>'Đã hủy','refunded'=>'Đã hoàn tiền'];
?>
<div class="section-heading"><div><p class="eyebrow">Bán hàng</p><h2>Quản lý đơn hàng</h2><p class="muted">Theo dõi trạng thái đơn và đối soát phương thức thanh toán.</p></div><a class="button" href="/admin/reports">Báo cáo thanh toán</a></div>
<?php if (!empty($error)): ?><div class="notice"><?= ViewHelper::escape($error) ?></div><?php endif; ?>
<?php if (empty($orders)): ?><div class="empty-state"><h2>Chưa có đơn hàng</h2><p>Đơn hàng sẽ xuất hiện sau khi khách đặt hàng.</p></div><?php else: ?><div class="table-wrap"><table class="admin-table"><thead><tr><th>Mã đơn</th><th>Khách hàng</th><th>Tổng tiền</th><th>Thanh toán</th><th>Ngày đặt</th><th>Trạng thái</th></tr></thead><tbody><?php foreach ($orders as $order): ?><tr><td><?= ViewHelper::escape($order['order_code']) ?></td><td><?= ViewHelper::escape($order['customer_name']) ?><br><small><?= ViewHelper::escape($order['customer_email']) ?></small></td><td><?= ViewHelper::money((int)$order['total']) ?></td><td><span class="report-badge report-badge-neutral"><?= ViewHelper::escape($paymentMethods[$order['payment_method'] ?? 'cod'] ?? ($order['payment_method'] ?? 'COD')) ?></span><br><small><?= ViewHelper::escape($paymentStatuses[$order['payment_status'] ?? 'pending'] ?? ($order['payment_status'] ?? 'Chờ thanh toán')) ?></small></td><td><?= ViewHelper::escape($order['created_at']) ?></td><td><form method="post" action="/admin/orders/<?= (int)$order['id'] ?>/status"><?= Csrf::field() ?><label class="sr-only" for="order-status-<?= (int)$order['id'] ?>">Trạng thái đơn <?= ViewHelper::escape($order['order_code']) ?></label><select id="order-status-<?= (int)$order['id'] ?>" name="status"><option value="pending" <?= $order['status']==='pending'?'selected':'' ?>>Chờ xử lý</option><option value="confirmed" <?= $order['status']==='confirmed'?'selected':'' ?>>Đã xác nhận</option><option value="shipping" <?= $order['status']==='shipping'?'selected':'' ?>>Đang giao</option><option value="completed" <?= $order['status']==='completed'?'selected':'' ?>>Hoàn tất</option><option value="cancelled" <?= $order['status']==='cancelled'?'selected':'' ?>>Đã hủy</option></select><button class="action-button" type="submit">Lưu</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
